const props=defineProps({node:Object,theme:Object,playing:Boolean,assets:Object,interactive:Boolean});const emit=defineEmits(['action']);const host=ref(),labels=ref([]),selected=ref(null),error=ref(''),loading=ref(true);let renderer,scene,camera,controls,observer,intersection,model,ring,mixer,frame,active=true,build=0,clock=0,last=0,labelLast=0,fly,ambient,key,draco,pointerStart,dirty=true,labelsDirty=true,surfaceWidth=0,surfaceHeight=0,environment,lastShadow=0,statStart=0,statFrames=0,statCalls=0,statPeak=0,statTriangles=0,slowWindows=0,nextDraw=0,statCpu=0,statSerial=0;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
function resetStats(){if(renderer)delete renderer.domElement.dataset.fps;statStart=0;statFrames=0;statCalls=0;statPeak=0;statTriangles=0;statCpu=0;nextDraw=0;slowWindows=0;}
function startFly(position,target){if(!camera)return;labelsDirty=true;fly={start:performance.now(),from:camera.position.clone(),to:new THREE.Vector3(...position),oldTarget:controls.target.clone(),target:new THREE.Vector3(...target)};}
function detailView(){const kind=props.node.props.variant;startFly(kind==='city'?[41,32,43]:kind==='agriculture'?[19,18,23]:[23,19,27],kind==='city'?[1,7,-2]:[0,2,0]);}
