function focus(p){const position=p.position?.clone?.()||new THREE.Vector3(Number(p.x)||0,Number(p.y)||0,Number(p.z)||0);if(props.node.type==='model'&&!p.world)model?.root.localToWorld(position);startFly(position.clone().add(new THREE.Vector3(17,14,20)).toArray(),position.toArray());selected.value={...p,name:p.name||'模型区域',value:Number(p.value)||98.6,unit:p.unit||'运行指数'};emit('action','click',{...p,name:p.name,value:p.value});}
async function load(){
 const generation=++build;loading.value=true;error.value='';selected.value=null;labels.value=[];labelsDirty=true;mixer?.stopAllAction();mixer=null;while(scene.children.length){const o=scene.children[0];scene.remove(o);disposeObject(o);}const lights=lightWorld(scene,renderer,props.node.props,props.theme,environment);ambient=lights.ambient;key=lights.key;lastShadow=0;dirty=true;
 try{const p=props.node.props;if(props.node.type==='model'&&(props.assets[p.assetId]||p.url)){
  const loader=new GLTFLoader();if(p.draco){draco||=new DRACOLoader();draco.setDecoderPath('https://www.gstatic.com/draco/versioned/decoders/1.5.7/');loader.setDRACOLoader(draco);}const gltf=await loader.loadAsync(sitePath(props.assets[p.assetId]||p.url));if(generation!==build){disposeObject(gltf.scene);return;}const root=gltf.scene,box=new THREE.Box3().setFromObject(root),center=box.getCenter(new THREE.Vector3()),size=box.getSize(new THREE.Vector3()),scale=30/Math.max(size.x,size.y,size.z,.01);root.position.sub(center);const group=new THREE.Group();group.add(root);group.scale.setScalar(scale*p.modelScale);scene.add(group);root.traverse(o=>{if(!o.isMesh)return;o.castShadow=true;o.receiveShadow=true;o.userData.poi={name:o.name||'模型区域',value:98.6,unit:'运行指数'};if(p.material!=='original'){const old=o.material;const color=p.material==='white'?'#cbdce2':props.theme.accent;const replacement=new THREE.MeshStandardMaterial({color,metalness:p.material==='metal'?.95:.45,roughness:.25,transparent:p.material==='glass',opacity:p.material==='glass'?.68:1,emissive:props.theme.accent,emissiveIntensity:p.material==='energy'?.7:.08});o.material=replacement;(Array.isArray(old)?old:[old]).forEach(m=>{for(const value of Object.values(m))if(value?.isTexture){value.image?.close?.();value.dispose();}m.dispose();});}});const modelUniform={value:0};if(p.shader)root.traverse(o=>{for(const m of o.material?(Array.isArray(o.material)?o.material:[o.material]):[]){if(!m.isMeshStandardMaterial)continue;m.onBeforeCompile=shader=>{shader.uniforms.astraTime=modelUniform;shader.uniforms.astraAccent={value:new THREE.Color(props.theme.accent)};shader.fragmentShader='uniform float astraTime;uniform vec3 astraAccent;\n'+shader.fragmentShader.replace('#include <emissivemap_fragment>','#include <emissivemap_fragment>\n totalEmissiveRadiance += astraAccent * pow(max(0.0,1.0-abs(vViewPosition.y+mod(astraTime*3.0,40.0)-20.0)*0.4),5.0)*0.6;');};m.needsUpdate=true;}});model={root:group,labels:p.poi.map((l,i)=>({...l,id:l.id||'custom-'+i,position:new THREE.Vector3(l.x,l.y,l.z)})),home:[40,25,40],target:[0,0,0],update(t){modelUniform.value=t;}};if(gltf.animations.length){mixer=new THREE.AnimationMixer(root);gltf.animations.forEach(clip=>mixer.clipAction(clip).play());}}
