  if(generation!==build)return;if(props.node.type!=='globe'&&(!p.sceneStyle||p.sceneStyle==='default'))ring=energyRing(scene,props.theme);else ring=null;
  if(p.terrain>0&&props.node.type!=='globe'){const geo=new THREE.PlaneGeometry(85,65,64,48),a=geo.attributes.position;for(let i=0;i<a.count;i++){const x=a.getX(i),y=a.getY(i);a.setZ(i,(Math.sin(x*.14)*Math.cos(y*.12)+1)*p.terrain*.2-1.2);}geo.computeVertexNormals();const mesh=new THREE.Mesh(geo,new THREE.MeshStandardMaterial({color:'#173e45',roughness:1,wireframe:p.material==='energy',transparent:true,opacity:.5}));mesh.rotation.x=-Math.PI/2;scene.add(mesh);}
  model?.update(clock,true);camera.fov=p.fov||38;camera.updateProjectionMatrix();camera.position.fromArray(p.camera||model.home);controls.target.fromArray(p.target||model.target);controls.minDistance=props.node.type==='globe'?20:8;controls.maxDistance=160;controls.update();loading.value=false;
 }catch(e){if(generation===build){error.value='模型加载失败，请检查文件、地址与跨域权限';loading.value=false;}}
}
function pointerDown(e){pointerStart={x:e.clientX,y:e.clientY};}
function pointerUp(e){if(!props.interactive||!pointerStart||Math.hypot(e.clientX-pointerStart.x,e.clientY-pointerStart.y)>5)return;const r=renderer.domElement.getBoundingClientRect(),ray=new THREE.Raycaster();ray.setFromCamera(new THREE.Vector2((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1),camera);const hits=ray.intersectObjects(scene.children,true),hit=hits.find(h=>h.object.userData.poi||h.object.userData.instances)||hits.find(h=>h.object.isMesh&&h.object!==ring);if(!hit)return;const nearest=model?.labels?.reduce((best,l)=>!best||l.position.distanceTo(hit.point)<best.position.distanceTo(hit.point)?l:best,null);const p=hit.object.userData.instances?.[hit.instanceId]||hit.object.userData.poi||nearest;if(!p)return;focus({...p,world:true,position:p.position||hit.point});}
function resize(){if(!host.value||!renderer)return;const r=host.value.getBoundingClientRect();if(!r.width||!r.height)return;const width=Math.max(1,Math.round(r.width)),height=Math.max(1,Math.round(r.height));if(width===surfaceWidth&&height===surfaceHeight)return;surfaceWidth=width;surfaceHeight=height;renderer.setSize(width,height,false);camera.aspect=host.value.clientWidth/Math.max(1,host.value.clientHeight);camera.updateProjectionMatrix();dirty=true;labelsDirty=true;}
onMounted(async()=>{try{scene=new THREE.Scene();camera=new THREE.PerspectiveCamera(38,1,.1,500);renderer=new THREE.WebGLRenderer({alpha:true,antialias:props.node.props.quality!=='performance',powerPreference:'high-performance'});renderer.setPixelRatio(Math.min(devicePixelRatio,props.node.props.quality==='high'?2:props.node.props.quality==='performance'?1:1.5));renderer.setClearColor(0,0);renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=props.node.props.exposure??1.12;try{environment=createStudioEnvironment(renderer,props.node.props.quality);}catch(e){console.warn('Scene reflections unavailable; using direct lighting.',e);}host.value.prepend(renderer.domElement);controls=new OrbitControls(camera,renderer.domElement);controls.addEventListener('change',()=>{dirty=true;labelsDirty=true;});controls.enableDamping=true;controls.enablePan=true;controls.maxPolarAngle=Math.PI*.48;controls.autoRotateSpeed=props.node.props.rotateSpeed;renderer.domElement.addEventListener('pointerdown',pointerDown);renderer.domElement.addEventListener('pointerup',pointerUp);renderer.domElement.addEventListener('webglcontextlost',lost);observer=new ResizeObserver(resize);observer.observe(host.value);const scaleSurface=host.value.closest('.aw-player-scaled,.aw-canvas-space');if(scaleSurface)observer.observe(scaleSurface);window.addEventListener('resize',resize);intersection=new IntersectionObserver(entries=>active=entries[0].isIntersecting);intersection.observe(host.value);resize();await load();if(!host.value)return;
 function draw(now){frame=requestAnimationFrame(draw);if(!active||document.hidden){statStart=now;statFrames=0;statCalls=0;statPeak=0;statTriangles=0;statCpu=0;nextDraw=0;last=0;return;}const cadence=1000/(props.node.props.quality==='high'?60:30);if(now+1<nextDraw)return;if(now-nextDraw>cadence*2)nextDraw=now;nextDraw+=cadence;const dt=last?Math.min(.08,(now-last)/1000):0;last=now;controls.enabled=props.interactive;controls.autoRotate=props.playing&&!reduced&&props.node.props.autoRotate;controls.autoRotateSpeed=props.node.props.rotateSpeed;if(fly){const t=Math.min(1,(now-fly.start)/1400),ease=t*t*(3-2*t);camera.position.lerpVectors(fly.from,fly.to,ease);controls.target.lerpVectors(fly.oldTarget,fly.target,ease);if(t===1)fly=null;}if(props.playing&&!reduced){clock+=dt;if(mixer&&props.node.props.modelAnimation)mixer.update(dt);if(props.node.props.modelSpin&&model)model.root.rotation.y+=dt*.15;}const renderStart=performance.now();model?.update(clock,props.playing&&!reduced);if(ring){ring.visible=props.node.props.energy;ring.material.uniforms.time.value=clock;}controls.update();if(!props.playing&&!fly&&!dirty)return;dirty=false;if(renderer.shadowMap.enabled&&(model?.dynamicShadows||props.node.props.modelSpin||(!!mixer&&props.node.props.modelAnimation))&&props.playing&&now-lastShadow>(props.node.props.quality==='high'?80:180)){renderer.shadowMap.needsUpdate=true;lastShadow=now;}renderer.render(scene,camera);statCpu+=performance.now()-renderStart;statFrames++;statCalls+=renderer.info.render.calls;statPeak=Math.max(statPeak,renderer.info.render.calls);statTriangles=Math.max(statTriangles,renderer.info.render.triangles);if(!statStart)statStart=now;if(now-statStart>=1200){const fps=statFrames*1000/(now-statStart);Object.assign(renderer.domElement.dataset,{fps:fps.toFixed(1),sample:++statSerial,quality:props.node.props.quality,frameCpuMs:(statCpu/statFrames).toFixed(2),drawCalls:Math.round(statCalls/statFrames),peakCalls:statPeak,triangles:statTriangles,dpr:renderer.getPixelRatio().toFixed(2),geometries:renderer.info.memory.geometries,textures:renderer.info.memory.textures});if(props.node.props.adaptiveQuality!==false&&props.playing){slowWindows=fps<23?slowWindows+1:0;if(slowWindows>=3&&renderer.getPixelRatio()>1){renderer.setPixelRatio(Math.max(1,renderer.getPixelRatio()-.25));dirty=true;slowWindows=0;}}statStart=now;statFrames=0;statCalls=0;statPeak=0;statTriangles=0;statCpu=0;}if(props.node.props.showPOI&&(labelsDirty||now-labelLast>250)){labelsDirty=false;labelLast=now;const w=host.value.clientWidth,h=host.value.clientHeight;model?.root.updateWorldMatrix(true,false);const placed=[];labels.value=(model?.labels||[]).map(p=>{const pos=p.position.clone();if(props.node.type==='model')model.root.localToWorld(pos);const q=pos.project(camera),width=Math.min(250,p.name.length*10+46),anchorX=(q.x+1)*w/2,anchorY=(1-q.y)*h/2;let x=Math.max(width/2+10,Math.min(w-width/2-10,anchorX)),y=Math.max(props.node.props.showHUD?96:42,Math.min(h-62,anchorY));const visible=q.z<1&&q.z>-1&&Math.abs(q.x)<.94&&Math.abs(q.y)<.9&&(props.node.type!=='globe'||p.position.dot(camera.position)>0);if(visible){for(let step=0;step<4;step++){const clash=placed.find(l=>Math.abs(l.x-x)<(l.width+width)/2+10&&Math.abs(l.y-y)<39);if(!clash)break;if(y+44<h-54)y+=44;else x=Math.max(width/2+10,Math.min(w-width/2-10,x+width*.8));}placed.push({x,y,width});}return {...p,x,y,anchorX,anchorY,adjusted:Math.hypot(x-anchorX,y-anchorY)>18,visible};});}}frame=requestAnimationFrame(draw);
 }catch{error.value='当前设备无法启用 WebGL，请启用硬件加速';loading.value=false;}});
function lost(e){e.preventDefault();error.value='WebGL 上下文已丢失，请重新加载场景';cancelAnimationFrame(frame);}
watch(()=>[props.node.type,props.node.props.variant,props.node.props.material,props.node.props.shader,props.node.props.terrain,props.node.props.assetId,props.node.props.url,props.node.props.modelScale,props.node.props.draco,props.node.props.sceneStyle,props.node.props.quality,props.node.props.shadows,props.theme.id],()=>{if(scene)load();});watch(()=>[...props.node.props.camera,...props.node.props.target],()=>{if(camera)startFly(props.node.props.camera,props.node.props.target);});watch(()=>props.node.props.fov,v=>{if(camera){camera.fov=Number(v)||38;camera.updateProjectionMatrix();dirty=true;}});watch(()=>props.node.props.showPOI,()=>{dirty=true;labelsDirty=true;});watch(()=>props.node.props.poi,value=>{if(model&&props.node.type==='model')model.labels=value.map((l,i)=>({...l,id:l.id||'custom-'+i,position:new THREE.Vector3(l.x,l.y,l.z)}));},{deep:true});watch(()=>props.assets,()=>{if(scene&&props.node.props.assetId)load();});watch(()=>[props.playing,props.node.props.energy],()=>dirty=true);watch(()=>props.playing,resetStats);watch(()=>props.node.props.exposure,v=>{if(renderer){renderer.toneMappingExposure=v;dirty=true;}});watch(()=>props.node.props.reflectionIntensity,v=>{if(scene){scene.environmentIntensity=v;dirty=true;}});watch(()=>props.node.props.quality,v=>{if(renderer){renderer.setPixelRatio(Math.min(devicePixelRatio,v==='high'?2:v==='performance'?1:1.5));resetStats();dirty=true;}});watch(()=>props.node.props.ambient,v=>{if(ambient){ambient.intensity=v*.3;dirty=true;}});watch(()=>props.node.props.directional,v=>{if(key){key.intensity=v;renderer.shadowMap.needsUpdate=true;dirty=true;}});
onBeforeUnmount(()=>{build++;cancelAnimationFrame(frame);observer?.disconnect();window.removeEventListener('resize',resize);intersection?.disconnect();mixer?.stopAllAction();controls?.dispose();renderer?.domElement.removeEventListener('pointerdown',pointerDown);renderer?.domElement.removeEventListener('pointerup',pointerUp);renderer?.domElement.removeEventListener('webglcontextlost',lost);disposeObject(scene);environment?.dispose();draco?.dispose();renderer?.dispose();renderer?.forceContextLoss();});
defineExpose({reset,focus,startFly});
</script>
<template><div ref="host" class="aw-spatial" :class="{'is-interactive':interactive}"><SceneOverlay v-if="node.props.showHUD&&!error" :node="node"/><div v-if="loading" class="aw-scene-state"><span class="aw-loading-ring"></span>正在构建空间场景</div><div v-if="error" class="aw-scene-state error">{{error}}<button @click.stop="load">重新加载</button></div><template v-if="node.props.showPOI&&!loading&&!error"><svg class="aw-poi-leaders" aria-hidden="true"><path v-for="p in labels.filter(l=>l.visible&&l.adjusted)" :key="p.id" :d="`M${p.x} ${p.y}V${p.y+12}L${p.anchorX} ${p.anchorY}`"/></svg><button v-for="p in labels.filter(l=>l.visible)" :key="p.id" class="aw-poi" :class="{'has-leader':p.adjusted}" :style="{left:p.x+'px',top:p.y+'px'}" @click.stop="focus(p)"><i></i>{{p.name}}<span>↗</span></button></template><div v-if="selected" class="aw-poi-card" @pointerdown.stop><button class="aw-poi-close" @click.stop="selected=null">×</button><span>空间单元 · 实时数据</span><h3>{{selected.name}}</h3><strong>{{Number(selected.value).toFixed(1)}}<small>{{selected.unit}}</small></strong><div><i></i>运行正常 <span>↑ 0.8%</span></div><button class="aw-poi-focus" @click.stop="focus(selected)">聚焦此区域 ↗</button></div><div v-if="interactive&&!error" class="aw-scene-controls" @pointerdown.stop><button @click.stop="detailView" title="近看场景细节" aria-label="近看场景细节"><svg viewBox="0 0 20 20" aria-hidden="true"><path d="M6 2H2V6M14 2H18V6M2 14V18H6M18 14V18H14M7 10H13M10 7V13"/></svg></button><button @click.stop="reset" title="重置视角" aria-label="重置视角"><svg viewBox="0 0 20 20" aria-hidden="true"><path d="M3 8A7 7 0 1 1 4 15M3 3V8H8"/></svg></button><button @click.stop="startFly([.1,65,.1],[0,0,0])" title="俯视场景" aria-label="俯视场景"><svg viewBox="0 0 20 20" aria-hidden="true"><path d="M3 3H17V17H3ZM3 10H17M10 3V17"/></svg></button></div></div></template>
